52	  useEffect(() => {
53	    if (open) {
54	      setStep('pickNF');
55	      setPickedNF(null);
56	      setBusca('');
57	      fetchNFs();
58	    }
59	    // fetchNFs is intentionally omitted — it's a stable async function defined in the same scope
60	    // eslint-disable-next-line react-hooks/exhaustive-deps
61	  }, [open]);
62	
63	  const fetchNFs = async () => {
64	    setLoading(true);
