import { useState, useEffect, useCallback } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Button } from '@/shared/ui/button';
import { Receipt, Search, ChevronRight, Loader2, Check } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';

interface CmvAtrelarNFDialogProps {
  open: boolean;
  cmvItemId: number | null;
  embalagemNome: string | null;
  currentNfItemId: number | null;
  onClose: () => void;
  onSaved: () => void;
}

type NF = {
  id: number;
  fornecedor: string | null;
  numero_nota: string | null;
  valor_total: number | null;
  data_nota: string | null;
};

type NFItem = {
  id: number;
  nota_id: number;
  nome_produto: string | null;
  quantidade: number | null;
  valor_unitario: number | null;
  subtotal: number | null;
  insumo_id: number | null;
};

export function CmvAtrelarNFDialog({
  open,
  cmvItemId,
  embalagemNome,
  currentNfItemId,
  onClose,
  onSaved,
}: CmvAtrelarNFDialogProps) {
  const [step, setStep] = useState<'pickNF' | 'pickItem'>('pickNF');
  const [nfs, setNfs] = useState<NF[]>([]);
  const [nfItems, setNfItems] = useState<NFItem[]>([]);
  const [pickedNF, setPickedNF] = useState<NF | null>(null);
  const [busca, setBusca] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  // Unidades por embalagem inseridas pelo usuário no passo pickItem
  const [unidadesPorEmbalagem, setUnidadesPorEmbalagem] = useState('');

  const fetchNFs = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('notas_fiscais')
      .select('id, fornecedor, numero_nota, valor_total, data_nota')
      .order('data_nota', { ascending: false })
      .limit(80);

    if (error) {
      toast.error('Erro ao buscar notas fiscais: ' + error.message);
    } else {
      setNfs((data ?? []) as NF[]);
    }
    setLoading(false);
  }, []);

  const fetchItems = useCallback(async (nfId: number) => {
    setLoading(true);
    const { data, error } = await supabase
      .from('itens_nota_fiscal')
      .select('id, nota_id, nome_produto, quantidade, valor_unitario, subtotal, insumo_id')
      .eq('nota_id', nfId);

    if (error) {
      toast.error('Erro ao buscar itens da nota: ' + error.message);
    } else {
      setNfItems((data ?? []) as NFItem[]);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    if (open) {
      setStep('pickNF');
      setPickedNF(null);
      setBusca('');
      setUnidadesPorEmbalagem('');
      fetchNFs();
    }
  }, [open, fetchNFs]);

  const handlePickNF = (nf: NF) => {
    setPickedNF(nf);
    setBusca('');
    setUnidadesPorEmbalagem('');
    setStep('pickItem');
    fetchItems(nf.id);
  };

  const handlePickItem = async (item: NFItem) => {
    if (!cmvItemId) return;
    setSaving(true);

    const unidades = parseFloat(unidadesPorEmbalagem) || null;

    const { error } = await supabase
      .from('cmv_itens')
      .update({
        nf_item_id: item.id,
        preco_unitario_esboco: null,
        ...(unidades !== null ? { unidades_por_embalagem: unidades } : {}),
      } as Record<string, unknown>)
      .eq('id', cmvItemId);

    setSaving(false);

    if (error) {
      toast.error('Erro ao atrelar NF: ' + error.message);
    } else {
      toast.success('Nota fiscal atrelada com sucesso');
      onSaved();
      onClose();
    }
  };

  const filteredNFs = nfs.filter(
    (n) =>
      (n.fornecedor?.toLowerCase() ?? '').includes(busca.toLowerCase()) ||
      (n.numero_nota?.toLowerCase() ?? '').includes(busca.toLowerCase()),
  );

  const filteredItems = nfItems.filter((i) =>
    (i.nome_produto?.toLowerCase() ?? '').includes(busca.toLowerCase()),
  );

  const formatDate = (d: string | null) => {
    if (!d) return '';
    try {
      return new Date(d).toLocaleDateString('pt-BR');
    } catch {
      return d;
    }
  };

  const formatMoney = (v: number | null) => {
    if (v === null) return 'R$ 0,00';
    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  // Dica de custo unitário calculado
  const unidadesNum = parseFloat(unidadesPorEmbalagem);

  return (
    <Dialog open={open} onOpenChange={(val) => !val && onClose()}>
      <DialogContent className="w-[min(672px,calc(100vw-2rem))] max-h-[82vh] flex flex-col bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl p-0 overflow-hidden">
        <DialogHeader className="p-4 border-b border-[#57715B]/10 shrink-0">
          <DialogTitle className="text-lg font-semibold text-[#2D362E] dark:text-[#E6DCCF]">
            Atrelar nota fiscal
          </DialogTitle>
          <p className="text-sm text-muted-foreground mt-0.5">
            {embalagemNome ?? 'Embalagem'}
          </p>

          {step === 'pickItem' && pickedNF && (
            <div className="flex items-center gap-2 text-sm text-muted-foreground mt-2">
              <Button
                variant="ghost"
                size="sm"
                className="h-6 px-2 text-xs hover:bg-[#57715B]/10 text-[#57715B]"
                onClick={() => {
                  setStep('pickNF');
                  setBusca('');
                }}
              >
                Outra NF
              </Button>
              <ChevronRight size={14} />
              <span className="font-medium text-[#57715B]">
                NF {pickedNF.numero_nota} - {pickedNF.fornecedor}
              </span>
            </div>
          )}

          {/* Campo unidades por embalagem — visível apenas no passo pickItem */}
          {step === 'pickItem' && (
            <div className="mt-3 space-y-1">
              <Label className="text-xs text-slate-600 dark:text-slate-300">
                Unidades por embalagem (ex.: caixa de 200)
              </Label>
              <Input
                type="number"
                min="1"
                placeholder="ex: 200"
                value={unidadesPorEmbalagem}
                onChange={(e) => setUnidadesPorEmbalagem(e.target.value)}
                className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
              />
              {unidadesNum > 0 && (
                <p className="text-[10px] text-muted-foreground">
                  Custo unitário será calculado: valor_item ÷ {unidadesNum}
                </p>
              )}
            </div>
          )}

          <div className="relative mt-3">
            <Search
              className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground"
              size={16}
            />
            <Input
              value={busca}
              onChange={(e) => setBusca(e.target.value)}
              placeholder={
                step === 'pickNF'
                  ? 'Buscar por fornecedor ou número...'
                  : 'Buscar por produto na nota...'
              }
              className="pl-9 bg-white/60 dark:bg-black/20 border-[#57715B]/15 rounded-xl focus-visible:ring-[#57715B]/30"
            />
          </div>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto p-2">
          {loading && (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="animate-spin text-[#57715B]" size={24} />
            </div>
          )}

          {!loading && step === 'pickNF' && (
            <div className="flex flex-col divide-y divide-[#57715B]/10">
              {filteredNFs.map((nf) => (
                <button
                  key={nf.id}
                  onClick={() => handlePickNF(nf)}
                  className="flex items-center justify-between p-3 text-left hover:bg-[#57715B]/5 transition-colors rounded-lg group"
                >
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-[#57715B]/10 rounded-lg text-[#57715B]">
                      <Receipt size={18} />
                    </div>
                    <div>
                      <div className="font-bold text-[#2D362E] dark:text-[#E6DCCF] group-hover:text-[#57715B] transition-colors">
                        {nf.fornecedor ?? 'Desconhecido'}
                      </div>
                      <div className="text-xs text-muted-foreground">
                        NF: {nf.numero_nota} • Data: {formatDate(nf.data_nota)}
                      </div>
                    </div>
                  </div>
                  <div className="font-medium tabular-nums text-[#57715B]">
                    {formatMoney(nf.valor_total)}
                  </div>
                </button>
              ))}
              {filteredNFs.length === 0 && (
                <div className="p-8 text-center text-muted-foreground text-sm">
                  Nenhuma nota fiscal encontrada.
                </div>
              )}
            </div>
          )}

          {!loading && step === 'pickItem' && (
            <div className="flex flex-col gap-1">
              {filteredItems.map((item) => {
                const isAlreadyLinked = item.id === currentNfItemId;
                const custoUnitario =
                  unidadesNum > 0 && item.valor_unitario != null
                    ? item.valor_unitario / unidadesNum
                    : null;

                return (
                  <button
                    key={item.id}
                    disabled={saving}
                    onClick={() => handlePickItem(item)}
                    className={`flex items-center justify-between p-3 text-left transition-colors rounded-xl ${
                      isAlreadyLinked
                        ? 'border-l-4 border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20'
                        : 'hover:bg-[#57715B]/5'
                    }`}
                  >
                    <div className="flex-1 pr-4">
                      <div className="font-medium text-[#2D362E] dark:text-[#E6DCCF] flex items-center gap-2">
                        {item.nome_produto}
                        {isAlreadyLinked && <Check size={14} className="text-emerald-600" />}
                      </div>
                      <div className="text-xs text-muted-foreground mt-1">
                        {item.quantidade} un × {formatMoney(item.valor_unitario)}
                        {custoUnitario != null && (
                          <span className="ml-2 text-[#57715B] font-medium">
                            → {formatMoney(custoUnitario)}/un
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="font-bold text-[#57715B] tabular-nums whitespace-nowrap">
                      {formatMoney(
                        item.subtotal ?? (item.quantidade ?? 0) * (item.valor_unitario ?? 0),
                      )}
                    </div>
                  </button>
                );
              })}
              {filteredItems.length === 0 && (
                <div className="p-8 text-center text-muted-foreground text-sm">
                  Nenhum item encontrado nesta nota.
                </div>
              )}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import {
  X,
  Package,
  DollarSign,
  ChefHat,
  Calculator,
  Receipt,
  Loader2,
  Save,
  Trash2,
  Calendar,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/shared/ui/alert-dialog';
import { CmvAtrelarNFDialog } from './CmvAtrelarNFDialog';
import type { RawCmvItem } from '@/features/financeiro/model/useCmvGraph';

interface CmvDetailPanelProps {
  selectedNodeId: string | null;
  cmv: {
    id: number;
    nome: string;
    status: string;
    custo_calculado: number | null;
  } | null;
  fichaData: {
    id: number;
    nome: string;
    custo_calculado: number | null;
    rendimento_quantidade: number;
    rendimento_unidade: string;
    status: string;
  } | null;
  items: RawCmvItem[];
  custoFichaUnitario: number;
  custoEmbalagens: number;
  custoAvulsos: number;
  custoTotal: number;
  nfEmbalagemItems: Array<{
    id: number;
    nota_id: number;
    nome_produto: string | null;
    valor_unitario: number | null;
    unidade: string | null;
    fornecedor: string | null;
    numero_nota: string | null;
    data_nota: string | null;
  }>;
  onClose: () => void;
  onRefetch: () => Promise<void>;
}

// Robustly parse the node id segments.
// Formats: "cmv_<id>", "ficha_<id>", "item_<id>", "nf_nota_<id>"
function parseNodeId(nodeId: string): { kind: string; kindId: number | null; isNotaNode: boolean } {
  if (nodeId.startsWith('nf_nota_')) {
    const raw = nodeId.slice('nf_nota_'.length);
    const id = parseInt(raw, 10);
    return { kind: 'nf', kindId: Number.isNaN(id) ? null : id, isNotaNode: true };
  }
  const underscoreIdx = nodeId.indexOf('_');
  if (underscoreIdx === -1) return { kind: nodeId, kindId: null, isNotaNode: false };
  const kind = nodeId.slice(0, underscoreIdx);
  const rawId = nodeId.slice(underscoreIdx + 1);
  const id = parseInt(rawId, 10);
  return { kind, kindId: Number.isNaN(id) ? null : id, isNotaNode: false };
}

export function CmvDetailPanel({
  selectedNodeId,
  cmv,
  fichaData,
  items,
  custoFichaUnitario,
  custoEmbalagens,
  custoAvulsos,
  custoTotal,
  nfEmbalagemItems,
  onClose,
  onRefetch,
}: CmvDetailPanelProps) {
  const [atrelarNFOpen, setAtrelarNFOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [editQty, setEditQty] = useState('');
  const [editUnit, setEditUnit] = useState('');
  const [editPreco, setEditPreco] = useState('');
  const [editObs, setEditObs] = useState('');
  const [editUnidadesPorEmbalagem, setEditUnidadesPorEmbalagem] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const formatMoney = (v: number | null | undefined) => {
    if (v == null) return 'R$ 0,00';
    return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  };

  const formatDate = (d: string | null) => {
    if (!d) return '';
    return new Date(d).toLocaleDateString('pt-BR');
  };

  const { kind, kindId, isNotaNode } = useMemo(
    () => (selectedNodeId ? parseNodeId(selectedNodeId) : { kind: '', kindId: null, isNotaNode: false }),
    [selectedNodeId],
  );

  const selectedItem = useMemo(() => {
    if (kind === 'item' && kindId !== null) return items.find((i) => i.id === kindId);
    return null;
  }, [kind, kindId, items]);

  const selectedNFItem = useMemo(() => {
    if (selectedItem?.nf_item_id) {
      return nfEmbalagemItems.find((n) => n.id === selectedItem.nf_item_id);
    }
    return null;
  }, [selectedItem, nfEmbalagemItems]);

  const selectedNotaNodesData = useMemo(() => {
    if (isNotaNode && kindId !== null) {
      return nfEmbalagemItems.find((n) => n.nota_id === kindId);
    }
    return null;
  }, [isNotaNode, kindId, nfEmbalagemItems]);

  useEffect(() => {
    if (selectedItem) {
      setEditQty(selectedItem.quantidade?.toString() ?? '');
      setEditUnit(selectedItem.unidade ?? '');
      setEditPreco(selectedItem.preco_unitario_esboco?.toString() ?? '');
      setEditObs(selectedItem.observacao ?? '');
      setEditUnidadesPorEmbalagem(selectedItem.unidades_por_embalagem?.toString() ?? '');
    }
  }, [selectedItem]);

  const handleSaveItem = async () => {
    if (!selectedItem) return;
    setIsSaving(true);

    const updates: Record<string, unknown> = {
      quantidade: parseFloat(editQty) || 0,
      unidade: editUnit,
      observacao: editObs,
      unidades_por_embalagem: parseFloat(editUnidadesPorEmbalagem) || 1,
    };

    if (
      selectedItem.tipo === 'outro' ||
      (selectedItem.tipo === 'embalagem' && !selectedItem.nf_item_id)
    ) {
      updates.preco_unitario_esboco = parseFloat(editPreco) || 0;
    }

    const { error } = await supabase.from('cmv_itens').update(updates).eq('id', selectedItem.id);
    setIsSaving(false);

    if (error) {
      toast.error('Erro ao salvar: ' + error.message);
    } else {
      toast.success('Item atualizado');
      onRefetch();
    }
  };

  const handleDeleteItem = async () => {
    if (!selectedItem) return;
    setIsDeleting(true);
    const { error } = await supabase.from('cmv_itens').delete().eq('id', selectedItem.id);
    setIsDeleting(false);
    setDeleteDialogOpen(false);

    if (error) {
      toast.error('Erro ao excluir: ' + error.message);
    } else {
      toast.success('Item excluído');
      onClose();
      onRefetch();
    }
  };

  const handleDesatrelarNF = async () => {
    if (!selectedItem) return;
    setIsSaving(true);
    const { error } = await supabase
      .from('cmv_itens')
      .update({ nf_item_id: null } as Record<string, unknown>)
      .eq('id', selectedItem.id);
    setIsSaving(false);
    if (error) {
      toast.error('Erro ao desatrelar: ' + error.message);
    } else {
      toast.success('NF desatrelada');
      onRefetch();
    }
  };

  if (!selectedNodeId) return null;

  return (
    <>
      <aside className="absolute top-14 right-0 bottom-0 w-full sm:w-[420px] z-20 bg-white/95 dark:bg-[#1A1A1A]/95 backdrop-blur-xl border-l border-[#57715B]/10 shadow-2xl overflow-y-auto overflow-x-hidden animate-in slide-in-from-right duration-300 flex flex-col">
        <header className="sticky top-0 bg-white/95 dark:bg-[#1A1A1A]/95 border-b border-[#57715B]/10 p-4 flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center gap-2">
            {kind === 'cmv' && <Calculator className="text-[#57715B]" size={20} />}
            {kind === 'ficha' && <ChefHat className="text-amber-500" size={20} />}
            {kind === 'item' && selectedItem?.tipo === 'embalagem' && (
              <Package className="text-blue-500" size={20} />
            )}
            {kind === 'item' && selectedItem?.tipo === 'outro' && (
              <DollarSign className="text-orange-500" size={20} />
            )}
            {isNotaNode && <Receipt className="text-cyan-500" size={20} />}
            <span className="font-semibold text-sm">
              {kind === 'cmv' && 'Resumo do CMV'}
              {kind === 'ficha' && 'Ficha Base'}
              {kind === 'item' && selectedItem?.tipo === 'embalagem' && 'Detalhes da Embalagem'}
              {kind === 'item' && selectedItem?.tipo === 'outro' && 'Detalhes do Custo Avulso'}
              {isNotaNode && 'Detalhes da Nota Fiscal'}
            </span>
          </div>
          <Button
            variant="ghost"
            size="icon"
            aria-label="Fechar painel"
            className="h-10 w-10 hover:bg-[#57715B]/10 active:bg-[#57715B]/10"
            onClick={onClose}
          >
            <X size={18} className="text-muted-foreground" />
          </Button>
        </header>

        <div className="p-5 flex-1 overflow-y-auto space-y-6">
          {kind === 'cmv' && cmv && (
            <div className="space-y-4">
              <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">{cmv.nome}</h2>
              <div className="grid grid-cols-2 gap-3">
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-3 border border-[#57715B]/10 flex flex-col">
                  <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold">
                    Ficha Unitária
                  </span>
                  <span className="text-lg font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF] mt-1">
                    {formatMoney(custoFichaUnitario)}
                  </span>
                </div>
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-3 border border-[#57715B]/10 flex flex-col">
                  <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold">
                    Embalagens
                  </span>
                  <span className="text-lg font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF] mt-1">
                    {formatMoney(custoEmbalagens)}
                  </span>
                </div>
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-3 border border-[#57715B]/10 flex flex-col">
                  <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-semibold">
                    Avulsos
                  </span>
                  <span className="text-lg font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF] mt-1">
                    {formatMoney(custoAvulsos)}
                  </span>
                </div>
                <div className="bg-[#57715B]/10 rounded-2xl p-3 border border-[#57715B]/20 flex flex-col">
                  <span className="text-[10px] uppercase tracking-wider text-[#57715B] font-bold">
                    Custo Total
                  </span>
                  <span className="text-xl font-black tabular-nums text-[#57715B] mt-1">
                    {formatMoney(custoTotal)}
                  </span>
                </div>
              </div>
            </div>
          )}

          {kind === 'ficha' && fichaData && (
            <div className="space-y-4">
              <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">{fichaData.nome}</h2>
              <div className="flex items-center gap-2">
                <span className="text-amber-600 bg-amber-50 dark:bg-amber-900/20 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider">
                  Rende: {fichaData.rendimento_quantidade} {fichaData.rendimento_unidade}
                </span>
                <span className="text-slate-600 bg-slate-100 dark:bg-slate-800 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider">
                  {fichaData.status}
                </span>
              </div>
              <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 mt-4">
                <div className="text-xs uppercase tracking-wider text-muted-foreground font-semibold mb-1">
                  Custo Total da Ficha
                </div>
                <div className="text-3xl font-black tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                  {formatMoney(fichaData.custo_calculado)}
                </div>
                {fichaData.rendimento_quantidade > 0 && (
                  <div className="text-emerald-600 font-bold text-lg tabular-nums mt-4 pt-4 border-t border-[#57715B]/10">
                    {formatMoney(
                      (fichaData.custo_calculado ?? 0) / fichaData.rendimento_quantidade,
                    )}{' '}
                    / unidade
                  </div>
                )}
              </div>
            </div>
          )}

          {kind === 'item' && selectedItem?.tipo === 'embalagem' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF] mb-1">
                  {selectedItem.produtoMaster?.nome ??
                    selectedItem.insumo?.nome ??
                    selectedItem.observacao ??
                    'Embalagem'}
                </h2>
              </div>

              {selectedNFItem ? (
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] uppercase tracking-wider text-[#57715B] font-bold flex items-center gap-1.5">
                      <Receipt size={12} /> NF Atrelada
                    </span>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-6 px-2 text-[10px] text-[#57715B] hover:bg-[#57715B]/10"
                      onClick={handleDesatrelarNF}
                      disabled={isSaving}
                    >
                      Usar valor fixo
                    </Button>
                  </div>
                  <div>
                    <div className="font-semibold text-sm">{selectedNFItem.fornecedor}</div>
                    <div className="text-xs text-muted-foreground flex items-center gap-2 mt-1">
                      <span>NF: {selectedNFItem.numero_nota}</span>
                      <span>•</span>
                      <span className="flex items-center gap-1">
                        <Calendar size={10} /> {formatDate(selectedNFItem.data_nota)}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-end justify-between pt-2 border-t border-[#57715B]/10">
                    <div className="text-lg font-bold tabular-nums text-[#2D362E] dark:text-[#E6DCCF]">
                      {formatMoney(selectedNFItem.valor_unitario)}
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      className="h-7 text-xs border-[#57715B]/20 hover:bg-[#57715B]/5"
                      onClick={() => setAtrelarNFOpen(true)}
                    >
                      Trocar NF
                    </Button>
                  </div>
                </div>
              ) : (
                <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold">
                      Valor Fixo
                    </span>
                    <Button
                      variant="outline"
                      size="sm"
                      className="h-7 text-xs border-[#57715B]/20 hover:bg-[#57715B]/5 text-[#57715B]"
                      onClick={() => setAtrelarNFOpen(true)}
                    >
                      <Receipt size={12} className="mr-1.5" /> Atrelar NF
                    </Button>
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Preço Unitário (R$)</Label>
                    <Input
                      type="number"
                      value={editPreco}
                      onChange={(e) => setEditPreco(e.target.value)}
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                </div>
              )}

              <div className="space-y-4">
                <div className="space-y-1">
                  <Label className="text-xs">Unidades por pacote/caixa</Label>
                  <Input
                    type="number"
                    value={editUnidadesPorEmbalagem}
                    onChange={(e) => setEditUnidadesPorEmbalagem(e.target.value)}
                    className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    placeholder="Ex: 100"
                  />
                  <p className="text-[10px] text-muted-foreground">
                    Quantas unidades vêm na embalagem comprada.
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <Label className="text-xs">Uso na Ficha (Qtd)</Label>
                    <Input
                      type="number"
                      value={editQty}
                      onChange={(e) => setEditQty(e.target.value)}
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Unidade de Uso</Label>
                    <Input
                      value={editUnit}
                      onChange={(e) => setEditUnit(e.target.value)}
                      className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                    />
                  </div>
                </div>
              </div>

              <div className="flex items-center justify-between p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border border-emerald-500/20">
                <span className="text-xs font-bold uppercase tracking-wider text-emerald-700 dark:text-emerald-400">
                  Custo Calculado
                </span>
                <span className="text-xl font-black tabular-nums text-emerald-700 dark:text-emerald-400">
                  {formatMoney(selectedItem.custo_calculado)}
                </span>
              </div>
            </div>
          )}

          {kind === 'item' && selectedItem?.tipo === 'outro' && (
            <div className="space-y-6">
              <div className="space-y-1">
                <Label className="text-xs">Nome / Observação</Label>
                <Input
                  value={editObs}
                  onChange={(e) => setEditObs(e.target.value)}
                  className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                />
              </div>

              <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                <div className="space-y-1">
                  <Label className="text-xs">Valor Fixo (R$)</Label>
                  <Input
                    type="number"
                    value={editPreco}
                    onChange={(e) => setEditPreco(e.target.value)}
                    className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label className="text-xs">Quantidade</Label>
                  <Input
                    type="number"
                    value={editQty}
                    onChange={(e) => setEditQty(e.target.value)}
                    className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs">Unidade</Label>
                  <Input
                    value={editUnit}
                    onChange={(e) => setEditUnit(e.target.value)}
                    className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                  />
                </div>
              </div>

              <div className="flex items-center justify-between p-4 bg-emerald-50 dark:bg-emerald-900/10 rounded-2xl border border-emerald-500/20">
                <span className="text-xs font-bold uppercase tracking-wider text-emerald-700 dark:text-emerald-400">
                  Custo Calculado
                </span>
                <span className="text-xl font-black tabular-nums text-emerald-700 dark:text-emerald-400">
                  {formatMoney(selectedItem.custo_calculado)}
                </span>
              </div>
            </div>
          )}

          {isNotaNode && selectedNotaNodesData && (
            <div className="space-y-4">
              <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">
                Nota Fiscal: {selectedNotaNodesData.numero_nota}
              </h2>
              <div className="bg-white/60 dark:bg-[#1A1A1A]/60 rounded-2xl p-4 border border-[#57715B]/10 space-y-3">
                <div className="flex justify-between items-start">
                  <span className="text-xs uppercase tracking-wider text-muted-foreground font-bold">
                    Fornecedor
                  </span>
                  <span className="text-sm font-semibold text-right">
                    {selectedNotaNodesData.fornecedor}
                  </span>
                </div>
                <div className="flex justify-between items-start">
                  <span className="text-xs uppercase tracking-wider text-muted-foreground font-bold">
                    Data da Nota
                  </span>
                  <span className="text-sm font-medium">
                    {formatDate(selectedNotaNodesData.data_nota)}
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>

        {kind === 'item' && selectedItem && (
          <div className="p-4 border-t border-[#57715B]/10 bg-white/95 dark:bg-[#1A1A1A]/95 shrink-0 flex items-center gap-2">
            <Button
              variant="outline"
              className="flex-1 border-red-200 text-red-600 hover:bg-red-50 hover:text-red-700 dark:border-red-900/30 dark:hover:bg-red-900/20 rounded-xl"
              onClick={() => setDeleteDialogOpen(true)}
              disabled={isDeleting || isSaving}
            >
              {isDeleting ? (
                <Loader2 size={16} className="animate-spin mr-2" />
              ) : (
                <Trash2 size={16} className="mr-2" />
              )}
              Excluir
            </Button>
            <Button
              className="flex-[2] bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl"
              onClick={handleSaveItem}
              disabled={isSaving || isDeleting}
            >
              {isSaving ? (
                <Loader2 size={16} className="animate-spin mr-2" />
              ) : (
                <Save size={16} className="mr-2" />
              )}
              Salvar Alterações
            </Button>
          </div>
        )}
      </aside>

      {/* Confirmação de exclusão com AlertDialog (sem window.confirm) */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-[#2D362E] dark:text-[#E6DCCF]">
              Excluir item?
            </AlertDialogTitle>
            <AlertDialogDescription>
              Esta ação não pode ser desfeita. O item será removido permanentemente do CMV.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="bg-white/60 dark:bg-black/20 border-[#57715B]/15 hover:bg-[#57715B]/5 rounded-xl">
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDeleteItem}
              className="bg-red-600 hover:bg-red-700 text-white rounded-xl"
            >
              {isDeleting ? <Loader2 size={14} className="animate-spin mr-1" /> : null}
              Excluir
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {selectedItem && (
        <CmvAtrelarNFDialog
          open={atrelarNFOpen}
          cmvItemId={selectedItem.id}
          embalagemNome={
            selectedItem.produtoMaster?.nome ??
            selectedItem.insumo?.nome ??
            selectedItem.observacao ??
            'Embalagem'
          }
          currentNfItemId={selectedItem.nf_item_id}
          onClose={() => setAtrelarNFOpen(false)}
          onSaved={onRefetch}
        />
      )}
    </>
  );
}
